const items = $input.all();
const result = [];
for (const item of items) {
  const job = item.json;
  if (job._empty) continue;
  const idBase = (job.job_url || (job.company + job.job_title)).replace(/[^a-zA-Z0-9]/g, '').toLowerCase();
  const hash = Array.from(idBase).reduce((acc, c) => (acc * 31 + c.charCodeAt(0)) & 0xffffffff, 0).toString(36);
  result.push({
    json: {
      ...job,
      job_id: hash,
      date_found: new Date().toISOString().split('T')[0]
    }
  });
}
return result;

const allItems = $input.all();

// First N items are the new jobs, then the existing sheet rows
// We need to access both - use $('Add Job ID').all() for new and $input for existing
const newJobs = $('Add Job ID').all().map(i => i.json);
const existingJobs = $input.all().map(i => i.json);

const existingUrls = new Set(existingJobs.map(j => j.job_url).filter(Boolean));
const existingKeys = new Set(existingJobs.map(j => `${j.company}||${j.job_title}`).filter(Boolean));

const deduped = newJobs.filter(job => {
  const urlExists = existingUrls.has(job.job_url);
  const keyExists = existingKeys.has(`${job.company}||${job.job_title}`);
  return !urlExists && !keyExists;
});

return deduped.map(job => ({ json: job }));

const SEARCH_KEYWORDS = [
  'async remote', 'asynchronous remote', 'worldwide remote', 'global remote',
  'work from anywhere', 'remote data analyst', 'remote data scientist',
  'remote ai marketing', 'remote marketing analyst', 'remote growth analyst',
  'remote bi analyst', 'remote automation specialist', 'remote ai workflow',
  'data analyst', 'data scientist', 'business intelligence', 'bi analyst',
  'marketing analyst', 'growth analyst', 'ai marketing', 'performance marketing',
  'marketing data', 'analytics', 'automation specialist', 'martech'
];

const items = $input.all();
return items.filter(item => {
  const job = item.json;
  const text = [
    job.job_title, job.description, job.tags, job.location_text
  ].join(' ').toLowerCase();
  return SEARCH_KEYWORDS.some(kw => text.includes(kw.toLowerCase()));
});

const REJECT_PHRASES = [
  'us only', 'usa only', 'united states only', 'canada only', 'uk only',
  'united kingdom only', 'eu only', 'europe only', 'european union only',
  'australia only', 'must be based in', 'must live in',
  'must be authorized to work in', 'must be legally authorized',
  'local work permit required', 'work permit required',
  'hybrid', 'on-site', 'onsite', 'on site', 'office required',
  'remote within country only', 'remote within us', 'remote within usa',
  'fixed us hours', 'fixed eu hours', 'us-based', 'us based',
  'must reside in', 'residents of', 'citizens only'
];

const KEEP_PHRASES = [
  'worldwide remote', 'global remote', 'work from anywhere', 'anywhere',
  'apac remote', 'apac', 'international contractors', 'contractor role',
  'b2b contractor', 'deel', 'remote.com', 'oyster', 'eor', 'remote first',
  'distributed team', 'fully distributed', 'globally distributed',
  'international team', 'global team', 'open to all countries',
  'open to international'
];

const items = $input.all();
const result = [];

for (const item of items) {
  const job = item.json;
  const text = [job.job_title, job.description, job.location_text, job.tags]
    .join(' ').toLowerCase();

  const hasRejectPhrase = REJECT_PHRASES.some(p => text.includes(p.toLowerCase()));
  const hasKeepPhrase = KEEP_PHRASES.some(p => text.includes(p.toLowerCase()));

  if (hasRejectPhrase && !hasKeepPhrase) {
    // Log rejection reason
    let rejectReason = REJECT_PHRASES.find(p => text.includes(p.toLowerCase()));
    job._hard_filter_rejected = true;
    job._reject_reason = `Hard filter: "${rejectReason}" detected`;
    // We'll handle rejected items in a separate path
    continue;
  }

  result.push({
    json: {
      ...job,
      hard_filter_passed: true,
      has_keep_phrase: hasKeepPhrase
    }
  });
}

return result;

