const item = $input.item.json;
const prevJob = $('Process in Batches').item.json;

try {
  const rawText = item.content?.[0]?.text || '{}';
  // Extract JSON from the response
  const jsonMatch = rawText.match(/\{[\s\S]*\}/);
  const parsed = jsonMatch ? JSON.parse(jsonMatch[0]) : {};

  return {
    json: {
      ...prevJob,
      taiwan_eligible: parsed.taiwan_eligible || 'unclear',
      taiwan_reason: parsed.reason || '',
      location_risk: parsed.location_risk || 'medium',
      timezone_risk: parsed.timezone_risk || 'medium',
      contractor_possible: parsed.contractor_possible || 'unclear',
      ai_decision: parsed.decision || 'manual_check'
    }
  };
} catch(e) {
  return {
    json: {
      ...prevJob,
      taiwan_eligible: 'unclear',
      taiwan_reason: 'AI parse error',
      location_risk: 'medium',
      timezone_risk: 'medium',
      contractor_possible: 'unclear',
      ai_decision: 'manual_check'
    }
  };
}

const job = $input.item.json;
const text = [job.job_title, job.description, job.tags, job.location_text]
  .join(' ').toLowerCase();

const ASYNC_HIGH = ['async', 'asynchronous', 'no meetings', 'minimal meetings', 'documentation first'];
const ASYNC_MEDIUM = ['flexible hours', 'flexible schedule', 'flexible working hours', 'work at your own pace'];
const ASYNC_LOW = ['distributed team', 'remote first', 'fully remote', 'low meeting culture', 'work across time zones'];
const ASYNC_REJECT = [
  'strict 9 to 5', 'fixed us hours', 'fixed est hours', 'fixed pst hours',
  'fixed cet hours', 'daily live calls required', 'must overlap full business day',
  'must be available during us business hours', 'synchronous'
];

const hasReject = ASYNC_REJECT.some(p => text.includes(p));
if (hasReject) {
  return { json: { ...job, async_level: 'rejected', _async_rejected: true } };
}

let asyncLevel = 'unknown';
if (ASYNC_HIGH.some(p => text.includes(p))) asyncLevel = 'high';
else if (ASYNC_MEDIUM.some(p => text.includes(p))) asyncLevel = 'medium';
else if (ASYNC_LOW.some(p => text.includes(p))) asyncLevel = 'low';

return { json: { ...job, async_level: asyncLevel } };

const job = $input.item.json;
const text = [job.job_title, job.description, job.tags].join(' ').toLowerCase();

const PRIMARY_ROLES = [
  'data analyst', 'data scientist', 'junior data scientist',
  'business intelligence analyst', 'bi analyst', 'marketing analyst',
  'performance marketing analyst', 'growth analyst', 'ai marketing specialist',
  'ai automation specialist', 'ai workflow consultant', 'creative strategist',
  'martech analyst', 'marketing data analyst', 'analytics engineer'
];

const ADJACENT_ROLES = [
  'digital marketing', 'seo analyst', 'ppc analyst', 'growth hacker',
  'product analyst', 'operations analyst', 'revenue analyst', 'crm analyst',
  'e-commerce analyst', 'content strategist', 'automation engineer',
  'data engineer', 'reporting analyst', 'insights analyst'
];

let roleCategory = 'other';
if (PRIMARY_ROLES.some(r => text.includes(r))) {
  roleCategory = 'primary';
} else if (ADJACENT_ROLES.some(r => text.includes(r))) {
  roleCategory = 'adjacent';
}

return { json: { ...job, role_category: roleCategory } };

const job = $input.item.json;
const text = [job.job_title, job.description, job.tags, job.location_text]
  .join(' ').toLowerCase();

let score = 0;
let scoreBreakdown = [];

// Taiwan eligibility (max 40 pts)
const worldwideTerms = ['worldwide', 'work from anywhere', 'global remote', 'anywhere', 'contractor'];
const apacTerms = ['apac', 'asia pacific', 'asia-pacific'];

if (job.taiwan_eligible === 'yes' || worldwideTerms.some(t => text.includes(t))) {
  score += 40;
  scoreBreakdown.push('Taiwan eligible: +40');
} else if (apacTerms.some(t => text.includes(t))) {
  score += 30;
  scoreBreakdown.push('APAC eligible: +30');
} else if (job.taiwan_eligible === 'unclear' && job.location_risk !== 'high') {
  score += 20;
  scoreBreakdown.push('Location unclear but not restricted: +20');
} else {
  score += 0;
  scoreBreakdown.push('Country restricted: +0');
}

// Async fit (max 25 pts)
if (job.async_level === 'high') {
  score += 25;
  scoreBreakdown.push('Clearly async: +25');
} else if (job.async_level === 'medium') {
  score += 20;
  scoreBreakdown.push('Flexible hours: +20');
} else if (job.async_level === 'low') {
  score += 15;
  scoreBreakdown.push('Distributed team: +15');
} else {
  score += 10;
  scoreBreakdown.push('Remote first: +10');
}

// Role fit (max 25 pts)
if (job.role_category === 'primary') {
  score += 25;
  scoreBreakdown.push('Primary role fit: +25');
} else if (job.role_category === 'adjacent') {
  score += 15;
  scoreBreakdown.push('Adjacent role: +15');
}

// Salary fit (max 25 pts)
const salaryText = (job.salary || '').toLowerCase();
const salaryNums = salaryText.match(/\d+[,.]?\d*/g);
let annualSalary = 0;
if (salaryNums && salaryNums.length > 0) {
  const num = parseFloat(salaryNums[salaryNums.length - 1].replace(',', ''));
  // If monthly (< 1000 treated as monthly in hundreds, > 1000 might be annual)
  // Rough heuristic: if number < 20000, treat as monthly USD
  annualSalary = num < 20000 ? num : num / 12;
}

if (annualSalary >= 5000) {
  score += 25;
  scoreBreakdown.push('Salary >$5k/mo: +25');
} else if (annualSalary >= 3000) {
  score += 15;
  scoreBreakdown.push('Salary >$3k/mo: +15');
} else if (job.salary && job.salary.trim() !== '') {
  score += 10;
  scoreBreakdown.push('Salary listed: +10');
}

// One sentence rule
const oneSentencePass = (
  job.taiwan_eligible !== 'no' &&
  job.location_risk !== 'high' &&
  job.timezone_risk !== 'high' &&
  job.async_level !== 'rejected'
);

return {
  json: {
    ...job,
    score,
    score_breakdown: scoreBreakdown.join(' | '),
    one_sentence_pass: oneSentencePass
  }
};

