const fitResponse = $input.item.json;
const originalJob = $('Score >= 70?').item.json;
const whyFit = fitResponse.content?.[0]?.text || '';

return {
  json: {
    ...originalJob,
    why_good_fit: whyFit
  }
};

const items = $input.all();
const allJobs = items[0]?.json?.all_jobs || [];

// Sort by score desc
allJobs.sort((a, b) => (b.score || 0) - (a.score || 0));

const topJobs = allJobs.filter(j => j.taiwan_eligible !== 'no').slice(0, 10);
const manualCheck = allJobs.filter(j => j.taiwan_eligible === 'unclear' && (j.score || 0) >= 70);
const rejectedUS = allJobs.filter(j => j.taiwan_reason && j.taiwan_reason.toLowerCase().includes('us'));
const rejectedEU = allJobs.filter(j => j.taiwan_reason && j.taiwan_reason.toLowerCase().includes('eu'));
const rejectedHybrid = allJobs.filter(j => j.taiwan_reason && j.taiwan_reason.toLowerCase().includes('hybrid'));
const rejectedTimezone = allJobs.filter(j => j.timezone_risk === 'high');

let html = `<h1>Daily Taiwan Eligible Async Remote Jobs</h1>`;
html += `<p><em>${new Date().toLocaleDateString('en-US', { timeZone: 'Asia/Taipei', weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })} | ${topJobs.length} jobs found today</em></p>`;

html += `<h2>Top Jobs Today</h2>`;

topJobs.forEach((job, i) => {
  html += `
  <div style="border:1px solid #ccc; padding:12px; margin:10px 0; border-radius:6px;">
    <h3>${i + 1}. ${job.job_title}</h3>
    <p><strong>Company:</strong> ${job.company}</p>
    <p><strong>Score:</strong> ${job.score}/100</p>
    <p><strong>Taiwan Eligible:</strong> ${job.taiwan_eligible}</p>
    <p><strong>Reason:</strong> ${job.taiwan_reason || 'N/A'}</p>
    <p><strong>Async Level:</strong> ${job.async_level}</p>
    <p><strong>Timezone Risk:</strong> ${job.timezone_risk}</p>
    <p><strong>Salary:</strong> ${job.salary || 'Not listed'}</p>
    <p><strong>Why it fits Jerry:</strong> ${job.why_good_fit || 'N/A'}</p>
    <p><a href="${job.job_url}">Apply →</a></p>
  </div>`;
});

if (manualCheck.length > 0) {
  html += `<h2>Manual Check Required</h2>`;
  html += `<p>These jobs scored high but Taiwan eligibility is unclear:</p><ul>`;
  manualCheck.forEach(job => {
    html += `<li><a href="${job.job_url}">${job.job_title} at ${job.company}</a> — Score: ${job.score} — ${job.taiwan_reason}</li>`;
  });
  html += `</ul>`;
}

html += `<h2>Rejected Summary</h2>`;
html += `<ul>`;
html += `<li>Rejected (US only): ${rejectedUS.length}</li>`;
html += `<li>Rejected (EU only): ${rejectedEU.length}</li>`;
html += `<li>Rejected (Hybrid/Onsite): ${rejectedHybrid.length}</li>`;
html += `<li>Rejected (Timezone risk): ${rejectedTimezone.length}</li>`;
html += `</ul>`;

return [{ json: { digest_html: html, total_jobs: allJobs.length, top_count: topJobs.length } }];
